<?php
require __DIR__.'/includes/module.php';$u=require_auth();require_permission('dashboard.view');$pdo=db();$business=(int)$u['business_id'];
$sum=$pdo->prepare("SELECT COUNT(*) invoice_count,COALESCE(SUM(CASE WHEN status!='Void' THEN total ELSE 0 END),0) billed,COALESCE(SUM(CASE WHEN status!='Void' THEN amount_paid ELSE 0 END),0) received,COALESCE(SUM(CASE WHEN status!='Void' THEN total-amount_paid ELSE 0 END),0) outstanding FROM invoices WHERE business_id=?");$sum->execute([$business]);$fin=$sum->fetch();
$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE business_id=?');$q->execute([$business]);$expense=(float)$q->fetchColumn();$q=$pdo->prepare('SELECT COUNT(*) FROM customers WHERE business_id=? AND archived_at IS NULL');$q->execute([$business]);$customers=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM leads WHERE business_id=? AND status='Open'");$q->execute([$business]);$leads=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT COUNT(*) FROM tasks WHERE business_id=? AND status!='Completed'");$q->execute([$business]);$tasks=(int)$q->fetchColumn();
$month=$pdo->prepare("SELECT DATE_FORMAT(invoice_date,'%b') label,COALESCE(SUM(total),0) amount FROM invoices WHERE business_id=? AND status!='Void' AND invoice_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY YEAR(invoice_date),MONTH(invoice_date),DATE_FORMAT(invoice_date,'%b') ORDER BY YEAR(invoice_date),MONTH(invoice_date)");$month->execute([$business]);$trend=$month->fetchAll();
$recent=$pdo->prepare('SELECT i.id,i.invoice_number,i.invoice_date,i.total,i.status,c.name customer FROM invoices i JOIN customers c ON c.id=i.customer_id WHERE i.business_id=? ORDER BY i.created_at DESC LIMIT 5');$recent->execute([$business]);$invoices=$recent->fetchAll();$due=$pdo->prepare("SELECT t.title,t.due_date,t.priority,c.name customer FROM tasks t LEFT JOIN customers c ON c.id=t.customer_id WHERE t.business_id=? AND t.status!='Completed' ORDER BY t.due_date IS NULL,t.due_date LIMIT 4");$due->execute([$business]);$upcoming=$due->fetchAll();
page_start('Overview','dashboard');
