<div class="metric-grid"><a class="metric-card" href="invoices.php"><div class="metric-top"><span class="metric-icon blue"><i class="ti ti-file-invoice"></i></span><span class="metric-trend">All time</span><button class="more-dot"><i class="ti ti-dots"></i></button></div><span class="metric-label">Total invoiced</span><strong><?=money($fin['billed'])?></strong><small><?=$fin['invoice_count']?> invoices issued</small></a><a class="metric-card" href="payments.php"><div class="metric-top"><span class="metric-icon green"><i class="ti ti-wallet"></i></span><span class="metric-trend positive">Collected</span><button class="more-dot"><i class="ti ti-dots"></i></button></div><span class="metric-label">Cash received</span><strong><?=money($fin['received'])?></strong><small>Recorded payments</small></a><a class="metric-card" href="invoices.php?status=Outstanding"><div class="metric-top"><span class="metric-icon amber"><i class="ti ti-hourglass"></i></span><span class="metric-trend">Open balance</span><button class="more-dot"><i class="ti ti-dots"></i></button></div><span class="metric-label">Outstanding</span><strong><?=money($fin['outstanding'])?></strong><small>Across unpaid invoices</small></a><a class="metric-card" href="expenses.php"><div class="metric-top"><span class="metric-icon violet"><i class="ti ti-credit-card"></i></span><span class="metric-trend">All time</span><button class="more-dot"><i class="ti ti-dots"></i></button></div><span class="metric-label">Expenses recorded</span><strong><?=money($expense)?></strong><small>Cash outflows tracked</small></a></div>
<div class="dashboard-grid"><section class="panel revenue-panel"><div class="panel-head"><div><h2>Revenue overview</h2><p>Invoice value over the last six months</p></div><span class="select-pill">Last 6 months <i class="ti ti-chevron-down"></i></span></div><div class="chart-summary"><strong><?=money($fin['billed'])?></strong><span>lifetime invoiced</span></div><div class="chart-wrap"><canvas id="revenueChart" aria-label="Monthly revenue"></canvas></div></section><section class="panel pipeline-panel"><div class="panel-head"><div><h2>At a glance</h2><p>A quick pulse on your workspace</p></div><a class="subtle-link" href="reports.php">Details <i class="ti ti-arrow-up-right"></i></a></div><div class="pulse-row"><span class="pulse-icon sky"><i class="ti ti-users"></i></span><span class="pulse-copy"><strong>Customers</strong><small>Your active relationships</small></span><b><?=$customers?></b></div><div class="pulse-row"><span class="pulse-icon lilac"><i class="ti ti-target"></i></span><span class="pulse-copy"><strong>Open leads</strong><small>Opportunities in progress</small></span><b><?=$leads?></b></div><div class="pulse-row"><span class="pulse-icon peach"><i class="ti ti-list-check"></i></span><span class="pulse-copy"><strong>Active tasks</strong><small>Things to keep moving</small></span><b><?=$tasks?></b></div><a class="pipeline-cta" href="tasks.php"><span><i class="ti ti-sparkles"></i> Keep your momentum</span><i class="ti ti-arrow-right"></i></a></section></div>
<div class="bottom-grid"><section class="panel table-panel"><div class="panel-head"><div><h2>Recent invoices</h2><p>Stay close to what’s moving</p></div><a class="subtle-link" href="invoices.php">All invoices <i class="ti ti-arrow-up-right"></i></a></div><div class="table-scroll"><table><thead><tr><th>INVOICE</th><th>CUSTOMER</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th></tr></thead><tbody><?php if(!$invoices):?><tr><td colspan="5" class="empty-row">Your invoices will show here once created.</td></tr><?php else:foreach($invoices as $inv):?><tr><td><a class="table-strong" href="invoice-view.php?id=<?=(int)$inv['id']?>"><?=e($inv['invoice_number'])?></a></td><td><?=e($inv['customer'])?></td><td><?=fmt_date($inv['invoice_date'])?></td><td class="table-strong"><?=money($inv['total'])?></td><td><span class="status <?=strtolower(str_replace(' ','-',e($inv['status'])))?>"><?=e($inv['status'])?></span></td></tr><?php endforeach;endif?></tbody></table></div></section><section class="panel tasks-panel"><div class="panel-head"><div><h2>Upcoming tasks</h2><p>Small steps, meaningful progress</p></div><a class="subtle-link" href="tasks.php">See all <i class="ti ti-arrow-up-right"></i></a></div><?php if(!$upcoming):?><div class="task-empty"><span class="empty-spark"><i class="ti ti-sparkles"></i></span><strong>Room to breathe.</strong><p>No open tasks right now. Enjoy the clear runway.</p></div><?php else:foreach($upcoming as $task):?><div class="task-row"><span class="task-check"><i class="ti ti-circle"></i></span><span class="task-copy"><strong><?=e($task['title'])?></strong><small><?=e($task['customer']?:'General task')?></small></span><span class="task-date"><?=fmt_date($task['due_date'])?></span></div><?php endforeach;endif?><a class="add-task-link" href="tasks.php"><i class="ti ti-plus"></i> Add a task</a></section></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>window.revenueLabels=<?=json_encode(array_column($trend,'label'))?>;window.revenueData=<?=json_encode(array_map('floatval',array_column($trend,'amount')))?></script><?php page_end();
